$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$wrapper = Decode ""

$routePath = Join-Path $root "app\api\brain\market-advice\[id]\route.ts"
$livePath = Join-Path $root "lib\multi-slot-live-coverage.ts"
$migrationDir = Join-Path $root "supabase\migrations"

foreach ($path in @($routePath, $livePath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.98 : fichier requis introuvable : $path"
    }
}

$route = [System.IO.File]::ReadAllText($routePath)
$live = [System.IO.File]::ReadAllText($livePath)

if (-not ($route.Contains("KLYX_MULTI_SLOT_ADVICE_12_84") -or $route.Contains("market_service_offers"))) {
    throw "12.98 : conseiller marche/offres introuvable."
}

if (-not $live.Contains("KLYX_MULTI_SLOT_LIVE_COVERAGE_12_95")) {
    throw "12.98 : live coverage 12.95 introuvable."
}

$migration96 = Get-ChildItem -LiteralPath $migrationDir -File | Select-String -Pattern "KLYX_GROUP_ATOMIC_LIVE_COVERAGE_12_96" -SimpleMatch -List

if (-not $migration96) {
    throw "12.98 : RPC live coverage 12.96 introuvable."
}

if (-not $route.Contains("KLYX_MULTI_SLOT_LIVE_ADVICE_12_98")) {
    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

    Copy-Item -LiteralPath $routePath -Destination ($routePath + ".bak-12-98-" + $timestamp) -Force

    $getRegex = [regex]'export\s+async\s+function\s+GET\s*\('
    $matches = $getRegex.Matches($route)

    if ($matches.Count -ne 1) {
        throw "12.98 : exactement un export GET etait attendu. Trouve : $($matches.Count)"
    }

    $route = $getRegex.Replace($route, "async function klyxMarketAdviceBeforeLiveFilter(", 1)

    $route = $route.TrimEnd() + "`r`n`r`n" + $wrapper.TrimStart() + "`r`n"

    [System.IO.File]::WriteAllText($routePath, $route, $utf8)
}

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.98 APPLIQUE"
Write-Host "======================================"
Write-Host "Advice multi-slot : LIVE"
Write-Host "Disponibilites actuelles : REVALIDEES"
Write-Host "Prestataire stale : RETIRE DU CLASSEMENT"
Write-Host "Candidat DB : RESYNCHRONISE"
Write-Host "Meilleur restant : RECOMMANDE"
Write-Host "Selection automatique : NON"
Write-Host "12.96/12.97 : DERNIERE BARRIERE"
Write-Host "======================================"
